package org.example;

import org.eclipse.jface.viewers.TreeViewer;

public class MyClass {
    private TreeViewer fTreeViewer; // Assuming fTreeViewer is initialized somewhere

    public void updateContent(Object parent, boolean refreshViewer) {
        if (refreshViewer) {
            fTreeViewer.refresh(parent);
        }
    }
}

